            even += 1
        else:
            odd += 1
        num = num // 10
    return (even, odd)

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    if num < 0:
        even_count *= -1
        odd_count *= -1
    return (even_count, odd_count)

